    {
      "term": "Pointed arches",
      "definition": "A type of arch with a sharp, pointed top, which directs the thrust more steeply downward than round arches, reducing the outward push on the walls."
    },
    {
      "term": "Ribbed vaults",
      "definition": "A type of vaulting where the weight of the ceiling is channelled along ribs to piers, distributing the load more evenly."
    },
    {
      "term": "Flying buttresses",
      "definition": "External half-arches that carry the remaining outward thrust from the upper walls across the side aisles to massive buttress piers, helping to distribute the load."
    },
    {
      "term": "Pinnacles",
      "definition": "Large, decorative structures placed on top of buttress piers to add weight and help turn the thrust downward into the foundations."
    },
    {
      "term": "Stained glass",
      "definition": "Colored glass used in windows, allowing for the creation of intricate and colorful designs."
    }
  ]
